var XP="",XM="",YP="",YM="";
function axisStep(dir,axis,wantPlus){var a=get_position();if(!move(dir))return false;var b=get_position();var d=axis===0?(b.x-a.x):(b.y-a.y);if(d===0)return false;var plus=d>0;if(axis===0){if(plus)XP=dir;else XM=dir;}else{if(plus)YP=dir;else YM=dir;}return plus===wantPlus;}
function tryAxis(axis,wantPlus){var k=axis===0?(wantPlus?XP:XM):(wantPlus?YP:YM);if(k&&axisStep(k,axis,wantPlus))return true;var c=axis===0?["East","West"]:["North","South"];for(var i=0;i<c.length;i++){if(axisStep(c[i],axis,wantPlus))return true;}return false;}
function sidestep(){var d=["North","South","East","West"];for(var i=0;i<4;i++){var a=get_position();if(move(d[i])){var b=get_position();if(b.x!==a.x||b.y!==a.y)return true;}}return false;}
function nav(tx,ty){for(var g=0;g<400;g++){var p=get_position();if(p.x===tx&&p.y===ty)return true;var ok=false;if(p.x!==tx)ok=tryAxis(0,tx>p.x);if(!ok&&p.y!==ty)ok=tryAxis(1,ty>p.y);if(!ok)ok=sidestep();if(!ok)return false;}var q=get_position();return q.x===tx&&q.y===ty;}
function sizeOf(){var s=get_size();if(typeof s==="number")return s;if(s&&typeof s==="object"){if(typeof s.width==="number")return s.width;if(typeof s.w==="number")return s.w;if(typeof s.x==="number")return s.x;}return 8;}
function inv(f){try{var v=get_inventory();if(v&&typeof v[f]==="number")return v[f];}catch(e){}return -1;}
function look(){try{return inspect();}catch(e){return null;}}
function tend(i){if(i&&i.damaged){try{repair();}catch(e){}}if(i&&(i.water===0||i.water===false)){try{water();}catch(e){}}}
var N=get_drone_count();if(typeof N!=="number"||N<1)N=1;
var ME=get_drone_id();var R=ME%N;var LEADER=(R===0);var W=sizeOf();
var tiles=[];
for(var row=R;row<W;row+=N){for(var x=0;x<W;x++){if(nav(x,row)){var i=look();if(!i||!i.crop)continue;tend(i);var j=look();if(j&&j.crop==="crystal")tiles.push({x:x,y:row});else if(j&&j.ready){try{harvest();}catch(e){}}}}}
var guard=0;
while(tiles.length>0&&guard<100){guard++;var nxt=[];for(var t=0;t<tiles.length;t++){if(!nav(tiles[t].x,tiles[t].y))continue;var i=look();if(!i||!i.crop)continue;if(i.damaged){try{repair();}catch(e){}}if(i.ready){try{harvest();}catch(e){}continue;}if(i.water===0||i.water===false){try{water();}catch(e){}}nxt.push(tiles[t]);}tiles=nxt;if(tiles.length>0)wait(20);}
if(LEADER){var waited=0;while(inv("crystal")<24&&waited<150){waited++;wait(25);}
if(inv("parts")<16){var okc=false;try{okc=craft("parts",8);}catch(e){okc=false;}
if(!okc){for(var c=0;c<8;c++){if(inv("boards")>=2&&inv("oil")>=1&&inv("crystal")>=1){var one=false;try{one=craft("parts",1);}catch(e){one=false;}if(!one)break;}else break;}}}}
var g2=0;while(g2<80){g2++;if(inv("parts")>=16&&inv("crystal")>=16)break;wait(25);}

