var DL={};var EDGES=[];
function keyOf(x,y){return x+","+y;}
function learnDir(d,dx,dy){if(!DL[d])DL[d]=[dx,dy];}
function invDir(d){var t=DL[d];if(!t)return null;for(var k in DL){if(DL[k][0]===-t[0]&&DL[k][1]===-t[1])return k;}return null;}
function dirFor(dx,dy){for(var k in DL){if(DL[k][0]===dx&&DL[k][1]===dy)return k;}return null;}
function addEdge(a,b){for(var i=0;i<EDGES.length;i++){if(EDGES[i][0]===a&&EDGES[i][1]===b)return;}EDGES.push([a,b]);}
function getDirs(s){if(!s)return[];var out=[];
if(s.exits){var e=s.exits;if(typeof e.length==="number"){for(var i=0;i<e.length;i++){var it=e[i];if(typeof it==="string")out.push(it);else if(it&&it.dir)out.push(it.dir);}}else{for(var kk in e){if(e[kk])out.push(kk);}}}
var names=["North","South","East","West"];
for(var j=0;j<4;j++){var n=names[j];var lo=n.toLowerCase();
if(s[n]===true||s[lo]===true){var dup=false;for(var q=0;q<out.length;q++){if(out[q]===n)dup=true;}if(!dup)out.push(n);}}
return out;}
function hasLoot(s){if(!s)return false;if(s.loot)return s.loot;if(s.relic)return s.relic;if(s.item)return s.item;if(s.items&&s.items.length)return s.items[0];return false;}
var START=get_position();
var known={};
function dfsPass(){var visited={};var stack=[];
var p=get_position();visited[keyOf(p.x,p.y)]=true;
var added=0;if(!known[keyOf(p.x,p.y)]){known[keyOf(p.x,p.y)]=true;added=1;}
var guard=0;
while(guard<900){guard++;
var s=null;try{s=sense();}catch(e){s=null;}
if(hasLoot(s)){try{collect();}catch(e){}}
var dirs=getDirs(s);
var moved=false;
for(var i=0;i<dirs.length;i++){var d=dirs[i];
var p0=get_position();
var ok=false;try{ok=move(d);}catch(e){ok=false;}
if(!ok)continue;
var p1=get_position();
var dx=p1.x-p0.x,dy=p1.y-p0.y;
if(dx===0&&dy===0)continue;
learnDir(d,dx,dy);
addEdge(keyOf(p0.x,p0.y),keyOf(p1.x,p1.y));
var k=keyOf(p1.x,p1.y);
if(!visited[k]){visited[k]=true;stack.push(d);moved=true;
if(!known[k]){known[k]=true;added++;}break;}
var back=invDir(d);
var ok2=false;
if(back){try{ok2=move(back);}catch(e){ok2=false;}}
if(!ok2){var names2=["North","South","East","West"];
for(var z=0;z<4;z++){var ppre=get_position();var t=false;try{t=move(names2[z]);}catch(e){t=false;}if(t){var ppost=get_position();if(ppost.x===p0.x&&ppost.y===p0.y){addEdge(keyOf(ppre.x,ppre.y),keyOf(ppost.x,ppost.y));break;}else{var bk=invDir(names2[z]);if(bk){try{move(bk);}catch(e){}}}}}}}
if(moved)continue;
if(stack.length===0)break;
var d2=stack.pop();
var iv=invDir(d2);var okb=false;
if(iv){try{okb=move(iv);}catch(e){okb=false;}}
if(!okb){var names3=["North","South","East","West"];
for(var z2=0;z2<4;z2++){var pb=get_position();var tb=false;try{tb=move(names3[z2]);}catch(e){tb=false;}if(tb){var pa=get_position();var tgt=DL[d2];if(tgt&&pa.x===pb.x-tgt[0]&&pa.y===pb.y-tgt[1]){break;}else{var bk2=invDir(names3[z2]);if(bk2){try{move(bk2);}catch(e){}}}}}}}
return added;}
var rounds=0;
while(rounds<4){rounds++;var ad=dfsPass();if(ad<=0)break;}
function bfsPath(fromK,toK){var adj={};
for(var i=0;i<EDGES.length;i++){var a=EDGES[i][0],b=EDGES[i][1];
if(!adj[a])adj[a]=[];adj[a].push(b);
if(!adj[b])adj[b]=[];adj[b].push(a);}
var q=[fromK];var prev={};prev[fromK]=null;var head=0;
while(head<q.length){var cur=q[head++];
if(cur===toK){var path=[];var c=toK;while(c){path.push(c);c=prev[c];}path.reverse();return path;}
var ns=adj[cur]||[];
for(var j=0;j<ns.length;j++){if(!(ns[j] in prev)){prev[ns[j]]=cur;q.push(ns[j]);}}}
return null;}
var cp=get_position();
var path=bfsPath(keyOf(cp.x,cp.y),keyOf(START.x,START.y));
if(path){
for(var w=1;w<path.length;w++){
var target=path[w].split(",");
var tx=parseInt(target[0],10),ty=parseInt(target[1],10);
var done2=false;
for(var tries=0;tries<6&&!done2;tries++){
var pp=get_position();
var ddx=tx-pp.x,ddy=ty-pp.y;
if(ddx===0&&ddy===0){done2=true;break;}
var dd=dirFor(ddx,ddy);
if(dd){var mok=false;try{mok=move(dd);}catch(e){mok=false;}
if(mok){var af=get_position();if(af.x===tx&&af.y===ty)done2=true;}
else{delete DL[dd];}
}
if(!done2&&dd===null||!done2&&tries>0){var names4=["North","South","East","West"];
var bestD=null;
for(var z3=0;z3<4;z3++){var pb2=get_position();var t2=false;try{t2=move(names4[z3]);}catch(e){t2=false;}
if(t2){var pa2=get_position();learnDir(names4[z3],pa2.x-pb2.x,pa2.y-pb2.y);
if(pa2.x===tx&&pa2.y===ty){bestD=names4[z3];break;}else{var bk3=invDir(names4[z3]);if(bk3){try{move(bk3);}catch(e){}}}}}
if(bestD)done2=true;else if(tries>=5)break;}
}}}}
